function drawSelectionBounds(svg,d){if(marquee){const x=Math.min(marquee.start.x,marquee.current.x),y=Math.min(marquee.start.y,marquee.current.y),w=Math.abs(marquee.current.x-marquee.start.x),h=Math.abs(marquee.current.y-marquee.start.y);svg.append(el('rect',{class:'marquee-selection',x,y,width:w,height:h}))}const nodes=d.nodes.filter(n=>selectedNodeIds.has(n.id));if(nodes.length>1){const x=Math.min(...nodes.map(n=>n.x)),y=Math.min(...nodes.map(n=>n.y)),r=Math.max(...nodes.map(n=>n.x+n.width)),b=Math.max(...nodes.map(n=>n.y+n.height));svg.append(el('rect',{class:'multi-selection-bounds',x:x-5,y:y-5,width:r-x+10,height:b-y+10}))}}
