function semanticFeatureEditor(obj){
  const children=[selectField('Type',obj.typeRef||'',typeOptions(project,obj),v=>edit(obj,'typeRef',v))];
  const mult=document.createElement('div');mult.className='multiplicity-editor';
  const lower=compactField('Lower',obj.multiplicityLower??'1'),upper=compactField('Upper',obj.multiplicityUpper??'1');
  const commitMultiplicity=()=>{const before={multiplicity:obj.multiplicity,multiplicityLower:obj.multiplicityLower,multiplicityUpper:obj.multiplicityUpper},result=setMultiplicity(obj,lower.input.value,upper.input.value);if(!result.ok){lower.input.setCustomValidity(result.message);lower.input.reportValidity();Object.assign(obj,before);return}lower.input.setCustomValidity('');checkpoint();commitLocal({type:'replace-project',project:structuredClone(project),expectedValue:before},`Updated multiplicity to ${result.value}`)};
  lower.input.addEventListener('blur',commitMultiplicity);upper.input.addEventListener('blur',commitMultiplicity);mult.append(lower.root,upper.root);children.push(mult);
  if(supportsDirection(obj))children.push(selectField('Direction',obj.direction||'inout',[['in','in'],['out','out'],['inout','inout']],v=>edit(obj,'direction',v)));
  if(supportsDefault(obj))children.push(field('Default value',obj.defaultValue||'',v=>edit(obj,'defaultValue',v),'blur'));
  if(obj.kind==='ValueProperty'||obj.kind==='FlowProperty'){
    children.push(selectField('Unit',obj.unitRef||'',allElements(project).filter(e=>e.kind==='Unit').map(e=>[e.id,qualifiedName(project,e.id)]),v=>edit(obj,'unitRef',v)));
    children.push(selectField('Quantity kind',obj.quantityKindRef||'',allElements(project).filter(e=>e.kind==='QuantityKind').map(e=>[e.id,qualifiedName(project,e.id)]),v=>edit(obj,'quantityKindRef',v)));
  }
  if(supportsConjugation(obj))children.push(checkField('Conjugated',Boolean(obj.isConjugated),v=>edit(obj,'isConjugated',v)));
  const issues=semanticIssues(project,obj);if(issues.length){const box=document.createElement('div');box.className='semantic-issues';for(const issue of issues){const row=document.createElement('div');row.className=`semantic-issue ${issue.severity}`;row.textContent=issue.message;box.append(row)}children.push(box)}
  return section('Semantic Feature',children)
}
function compactField(label,value){const root=document.createElement('label');root.className='field compact-field';const span=document.createElement('span');span.textContent=label;const input=document.createElement('input');input.value=value??'';input.inputMode='numeric';root.append(span,input);return{root,input}}
