    const legacy=(e.compartments[name]||[]).filter(x=>typeof x==='string');if(legacy.length){const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Imported display text';const ta=document.createElement('textarea');ta.value=legacy.join('\n');ta.onblur=()=>{const old=structuredClone(e.compartments[name]||[]),value=ta.value.split('\n').map(x=>x.trim()).filter(Boolean);e.compartments[name]=value;commitLocal({type:'set-compartment',elementId:e.id,name,value,expectedValue:old},`Updated imported ${def.label} text`)};details.append(summary,ta);list.append(details)}
