function selectedDiagramNodes(){const d=activeDiagram();return d?d.nodes.filter(n=>selectedNodeIds.has(n.id)):[]}
function commitNodeLayout(message){checkpoint();commitLocal({type:'replace-project',project:structuredClone(project)},message)}
function alignSelected(mode){const nodes=selectedDiagramNodes();if(nodes.length<2){log('Select at least two diagram elements.','warn');return}checkpoint();if(mode==='left'){const v=Math.min(...nodes.map(n=>n.x));nodes.forEach(n=>n.x=v)}else if(mode==='right'){const v=Math.max(...nodes.map(n=>n.x+n.width));nodes.forEach(n=>n.x=v-n.width)}else if(mode==='top'){const v=Math.min(...nodes.map(n=>n.y));nodes.forEach(n=>n.y=v)}else if(mode==='bottom'){const v=Math.max(...nodes.map(n=>n.y+n.height));nodes.forEach(n=>n.y=v-n.height)}else if(mode==='hcenter'){const v=nodes.reduce((a,n)=>a+n.x+n.width/2,0)/nodes.length;nodes.forEach(n=>n.x=v-n.width/2)}else if(mode==='vcenter'){const v=nodes.reduce((a,n)=>a+n.y+n.height/2,0)/nodes.length;nodes.forEach(n=>n.y=v-n.height/2)}commitLocal({type:'replace-project',project:structuredClone(project)},`Aligned ${nodes.length} symbols`)}
function distributeSelected(axis){const nodes=selectedDiagramNodes();if(nodes.length<3){log('Select at least three diagram elements.','warn');return}checkpoint();const sorted=[...nodes].sort((a,b)=>axis==='h'?a.x-b.x:a.y-b.y);if(axis==='h'){const first=sorted[0].x,last=sorted.at(-1).x+sorted.at(-1).width,total=sorted.reduce((a,n)=>a+n.width,0),gap=(last-first-total)/(sorted.length-1);let x=first;for(const n of sorted){n.x=x;x+=n.width+gap}}else{const first=sorted[0].y,last=sorted.at(-1).y+sorted.at(-1).height,total=sorted.reduce((a,n)=>a+n.height,0),gap=(last-first-total)/(sorted.length-1);let y=first;for(const n of sorted){n.y=y;y+=n.height+gap}}commitLocal({type:'replace-project',project:structuredClone(project)},`Distributed ${nodes.length} symbols`)}
function nudgeSelection(dx,dy){const nodes=selectedDiagramNodes();if(!nodes.length)return;checkpoint();nodes.forEach(n=>{n.x+=dx;n.y+=dy});commitLocal({type:'replace-project',project:structuredClone(project)},`Moved ${nodes.length} symbol${nodes.length===1?'':'s'}`)}

function deleteSelected(){const d=activeDiagram();if(selected.nodeId){const n=d.nodes.find(x=>x.id===selected.nodeId);checkpoint();d.nodes=d.nodes.filter(x=>x.id!==selected.nodeId);commitLocal({type:'remove-presentation',diagramId:d.id,nodeId:selected.nodeId},'Removed diagram presentation');selected={type:null,id:null,nodeId:null,edgeId:null};return}if(selected.type==='relationship'){checkpoint();project.relationships=project.relationships.filter(x=>x.id!==selected.id);for(const x of project.diagrams)x.edges=x.edges.filter(e=>e.relationshipId!==selected.id);commitLocal({type:'delete-relationship',relationshipId:selected.id},'Deleted relationship');selected={type:null,id:null};return}if(selected.type==='element'&&selected.id!==project.root.id){if(!confirm('Delete this element, its owned elements, relationships, and presentations?'))return;checkpoint();const id=selected.id;applyDeleteLocal(id);commitLocal({type:'delete-element',elementId:id},'Deleted model element');selected={type:null,id:null}}}
function applyDeleteLocal(id){const ids=new Set([id]);let changed=true;while(changed){changed=false;for(const e of project.elements)if(ids.has(e.ownerId)&&!ids.has(e.id)){ids.add(e.id);changed=true}}project.elements=project.elements.filter(e=>!ids.has(e.id));project.relationships=project.relationships.filter(r=>!ids.has(r.sourceId)&&!ids.has(r.targetId));for(const d of project.diagrams){d.nodes=d.nodes.filter(n=>!ids.has(n.elementId));const valid=new Set(project.relationships.map(r=>r.id));d.edges=d.edges.filter(e=>valid.has(e.relationshipId))}}
function reuse(){const d=activeDiagram(),term=prompt('Search existing element by name or ID','');if(term===null)return;if(isIBD(d)){const ownerNode=d.nodes.find(node=>node.id===selected.nodeId)||d.nodes.find(node=>node.isContextBoundary),propertyCandidates=(ownerNode&&!ownerNode.isContextBoundary?availableNestedProperties(project,d,ownerNode):availableIBDProperties(project,d)).map(item=>item.element),portCandidates=availableIBDPorts(project,d,ownerNode),matches=[...propertyCandidates,...portCandidates].filter(e=>`${e.name} ${e.externalId} ${e.kind}`.toLowerCase().includes(term.toLowerCase()));if(!matches.length){log('No owned or inherited IBD property/port matched.','warn');return}const e=matches[0];try{checkpoint();const n=['PartProperty','ReferenceProperty'].includes(e.kind)?(ownerNode&&!ownerNode.isContextBoundary?createNestedPropertyPresentation(project,d,ownerNode,e.id,{relativeX:24,relativeY:42}):createIBDPropertyPresentation(project,d,e.id,{x:100+d.nodes.length*30,y:100+d.nodes.length*25})):createIBDPortPresentation(project,d,e.id,ownerNode);selected={type:'element',id:e.id,nodeId:n.id,edgeId:null};commitLocal({type:'add-presentation',diagramId:d.id,node:structuredClone(n)},`Placed existing ${e.kind} ${e.name}`)}catch(error){log(error.message,'error')}return}const matches=allElements(project).filter(e=>`${e.name} ${e.externalId} ${e.kind}`.toLowerCase().includes(term.toLowerCase())&&allowed(d.diagramType).elements.includes(e.kind));if(!matches.length){log('No valid reusable element found.','warn');return}const e=matches[0];if(d.nodes.some(n=>n.elementId===e.id)){log('Element is already shown on this diagram.','warn');return}const n={id:uid('node'),elementId:e.id,x:100+d.nodes.length*30,y:100+d.nodes.length*25,width:widthFor(e.kind),height:heightFor(e.kind)};checkpoint();d.nodes.push(n);commitLocal({type:'add-presentation',diagramId:d.id,node:structuredClone(n)},`Reused ${e.name}`)}
function search(){const q=$('searchBox').value.trim().toLowerCase();if(!q)return;const e=allElements(project).find(x=>`${x.name} ${x.externalId} ${x.stereotype} ${x.kind}`.toLowerCase().includes(q));if(e){selected={type:'element',id:e.id,nodeId:null,edgeId:null};view='model';render();return}log('No model element matched.','warn')}
function createDiagram(){const name=prompt('Diagram name','New Diagram');if(!name)return;const type=prompt(`Diagram type:\n${DIAGRAM_TYPES.join('\n')}`,'Block Definition Diagram');if(!DIAGRAM_TYPES.includes(type)){log('Invalid diagram type.','error');return}const owner=selected.type==='element'?selected.id:project.root.id;if(type==='Internal Block Diagram'&&findElement(project,owner)?.kind!=='Block'){log('Select a Block before creating an Internal Block Diagram.','error');return}const d={id:uid('diagram'),externalId:uid('DGM').toUpperCase(),name,diagramType:type,ownerId:owner,contextId:owner,nodes:[],edges:[],documentation:''};checkpoint();project.diagrams.push(d);normalizeIBDProject(project);project.activeDiagramId=d.id;commitLocal({type:'create-diagram',diagram:structuredClone(d)},'Created diagram')}
function defs(svg){const d=el('defs');d.innerHTML='<marker id="open" markerWidth="12" markerHeight="12" refX="11" refY="6" orient="auto"><path d="M1,1 L11,6 L1,11" fill="none" stroke="#263746"/></marker><marker id="triangle" markerWidth="14" markerHeight="14" refX="13" refY="7" orient="auto"><path d="M1,1 L13,7 L1,13 Z" fill="white" stroke="#263746"/></marker><marker id="diamond" markerWidth="16" markerHeight="12" refX="15" refY="6" orient="auto"><path d="M1,6 L7,1 L15,6 L7,11 Z" fill="white" stroke="#263746"/></marker><marker id="diamondFilled" markerWidth="16" markerHeight="12" refX="15" refY="6" orient="auto"><path d="M1,6 L7,1 L15,6 L7,11 Z" fill="#263746" stroke="#263746"/></marker>';svg.append(d)}function el(n,a={}){const x=document.createElementNS('http://www.w3.org/2000/svg',n);for(const[k,v]of Object.entries(a))if(v!==''&&v!=null)x.setAttribute(k,v);return x}function text(p,v,x,y,anchor='start',cls=''){const t=el('text',{x,y,'text-anchor':anchor,class:cls});t.textContent=v;p.append(t)}function wrap(p,v,x,y,w,h){let line='',row=0;for(const word of String(v).split(/\s+/)){const test=`${line} ${word}`.trim();if(test.length*6>w&&line){text(p,line,x,y+row*h);line=word;row++}else line=test}if(line)text(p,line,x,y+row*h)}function point(svg,e){const r=svg.getBoundingClientRect();return{x:(e.clientX-r.left)/zoom,y:(e.clientY-r.top)/zoom}}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function widthFor(k){return k==='Actor'?100:k==='UseCase'?180:['InitialNode','InitialPseudostate','ActivityFinalNode','FinalState','DecisionNode','MergeNode'].includes(k)?40:['ForkNode','JoinNode'].includes(k)?100:k==='Lifeline'?140:190}function heightFor(k){return k==='Actor'?120:k==='UseCase'?90:['InitialNode','InitialPseudostate','ActivityFinalNode','FinalState','DecisionNode','MergeNode'].includes(k)?40:['ForkNode','JoinNode'].includes(k)?20:k==='Lifeline'?45:110}function download(n,d,t){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([d],{type:t}));a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

function updateActionStates(){
  const connected=connectionState==='Connected';
  const hasSelection=Boolean(selected?.id||selected?.nodeId||selected?.edgeId);
  const hasElement=selected?.type==='element'&&Boolean(selected.id);
  const selectedElement=hasElement?findElement(project,selected.id):null;
  const childCapable=['Block','Activity','StateMachine','Interaction'].includes(selectedElement?.kind);
  const set=(id,disabled,reason='')=>{const b=$(id);if(!b)return;b.disabled=Boolean(disabled);b.title=disabled&&reason?reason:(b.dataset.defaultTitle||b.title||'');if(!b.dataset.defaultTitle)b.dataset.defaultTitle=b.title||''};
  set('undo',!history.length,'No local change to undo');set('redo',!future.length,'No local change to redo');
  set('deleteSelected',!hasSelection,'Select a presentation, relationship, or model element');
  set('openChild',!childCapable,'Select a Block, Activity, StateMachine, or Interaction');
  set('lockSelected',!connected||!hasElement,!connected?'Connect to a collaboration room first':'Select a model element');
  set('unlockSelected',!connected||!hasElement,!connected?'Connect to a collaboration room first':'Select a model element');
  for(const id of ['commitModel','newBranch','mergeBranch'])set(id,!connected,'Connect to a collaboration room first');
  $('branchSelect').disabled=!connected;
  const d=activeDiagram();set('routeEdges',!d||!d.edges?.length,'The active diagram has no relationships to route');
  set('reuseElement',!d,'Open a diagram first');set('newDiagram',false);set('validateModel',false);
  document.querySelectorAll('.menu-popover button[data-target]').forEach(menuButton=>{const target=$(menuButton.dataset.target);menuButton.disabled=Boolean(target?.disabled);menuButton.title=target?.title||''});
}
function wireMenus(){
  document.querySelectorAll('.menu-popover button[data-target]').forEach(button=>button.addEventListener('click',()=>{const target=$(button.dataset.target);button.closest('details')?.removeAttribute('open');if(target&&!target.disabled)target.click()}));
  document.addEventListener('click',event=>{for(const menu of document.querySelectorAll('.app-menu[open]'))if(!menu.contains(event.target))menu.removeAttribute('open');if(treeContextMenu&&!treeContextMenu.contains(event.target))closeTreeContextMenu()});
}


