$('diagramSelect').onchange=e=>navigateDiagram(e.target.value);$('newDiagram').onclick=createDiagram;$('newProject').onclick=()=>{if(!confirm('Create a new project?'))return;project=createProject(prompt('Project name','New Systems Model')||'New Systems Model');selected={};save();render()};$('saveProject').onclick=()=>{save();log('Saved locally.','ok')};$('exportProject').onclick=()=>download(`${project.name.replace(/\W+/g,'_')}.sysml.json`,JSON.stringify(project,null,2),'application/json');$('openProject').onclick=()=>$('fileInput').click();$('fileInput').onchange=async e=>{const f=e.target.files[0];if(f){project=normalizeProject(JSON.parse(await f.text()));save();render()}};$('importWorkbook').onclick=()=>$('workbookInput').click();$('workbookInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;const before=JSON.stringify(project);try{await importWorkbook(f,project,log,{strict:true});const issues=validate(project),errors=issues.filter(x=>x.severity==='error');if(errors.length&&!confirm(`Import has ${errors.length} errors. Keep staged import?`)){project=JSON.parse(before);render();return}commitLocal({type:'bulk-import',project:structuredClone(project)},`Imported ${f.name}`)}catch(err){project=JSON.parse(before);log(err.message,'error')}};$('validateModel').onclick=()=>{const issues=validate(project);if(!issues.length)log('SysML validation passed.','ok');else issues.forEach(i=>log(`${i.severity.toUpperCase()} [${i.code}] ${i.message}`,i.severity==='error'?'error':'warn'))};$('undo').onclick=()=>{if(!history.length)return;future.push(JSON.stringify(project));project=normalizeProject(JSON.parse(history.pop()));save();render();collab.publish({type:'replace-project',project:structuredClone(project)});log('Undid local change and synchronized the room.','ok')};$('redo').onclick=()=>{if(!future.length)return;history.push(JSON.stringify(project));project=normalizeProject(JSON.parse(future.pop()));save();render();collab.publish({type:'replace-project',project:structuredClone(project)});log('Redid local change and synchronized the room.','ok')};$('deleteSelected').onclick=deleteSelected;$('reuseElement').onclick=reuse;$('openChild').onclick=openChildForSelected;$('searchButton').onclick=search;$('searchBox').onkeydown=e=>{if(e.key==='Enter')search()};$('routeEdges').onclick=routeAll;$('zoomIn').onclick=()=>{zoom=Math.min(2.5,zoom+.1);renderCanvas()};$('zoomOut').onclick=()=>{zoom=Math.max(.25,zoom-.1);renderCanvas()};$('zoomReset').onclick=()=>{zoom=1;renderCanvas()};$('connectRoom').onclick=()=>{const settings={displayName:$('displayName').value,roomId:$('roomId').value,branchId:$('branchSelect').value};saveCollaborationSettings(localStorage,settings);history.replaceState(null,'',collaborationLink(location,settings));collab.setName(settings.displayName.trim()||'Modeler');collab.connect(settings.roomId.trim()||'default',settings.branchId||'main')};$('copyRoomLink').onclick=async()=>{const settings={roomId:$('roomId').value,branchId:$('branchSelect').value};const link=collaborationLink(location,settings);try{await navigator.clipboard.writeText(link);log('Collaboration room link copied.','ok')}catch{prompt('Copy this collaboration room link',link)}};$('commitModel').onclick=()=>{const m=prompt('Commit message','Model update');if(m)collab.commit(m)};$('newBranch').onclick=()=>{const n=prompt('Branch name','feature');if(n)collab.createBranch(n)};$('branchSelect').onchange=e=>collab.switchBranch(e.target.value);$('mergeBranch').onclick=()=>{const from=prompt('Branch ID to merge into current branch','');if(from)collab.send({type:'merge-branch',sourceBranchId:from,targetBranchId:collab.branchId})};$('lockSelected').onclick=()=>selected.id&&collab.lock(selected.id,300000);$('unlockSelected').onclick=()=>selected.id&&collab.unlock(selected.id);$('clearLog').onclick=()=>$('log').replaceChildren();$('help').onclick=()=>alert('Create a diagram, choose a palette tool, and click the canvas. Choose a relationship, then click source and target. Double-click a Block, Activity, StateMachine, or Interaction to open its child diagram.');

function isEditingTarget(target){return target?.matches?.('input,textarea,select,[contenteditable="true"]')}
function setSelectMode(){tool=null;sourceId=null;renderPalette();$('canvasWrap').classList.add('select-mode');log('Select mode.','ok')}
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!isEditingTarget(e.target)){spacePan=true;e.preventDefault()}if(isEditingTarget(e.target))return;const mod=e.ctrlKey||e.metaKey;if(e.key==='Escape'){closeTreeContextMenu();setSelectMode();selectedNodeIds.clear();selected={type:null,id:null,nodeId:null,edgeId:null};renderCanvas();renderProperties();e.preventDefault()}else if(e.key==='F2'&&selected?.id){beginTreeRename(selected.id,selected.type);e.preventDefault()}else if(mod&&e.key.toLowerCase()==='c'&&selected.type==='element'){copyTreeElement(selected.id);e.preventDefault()}else if(mod&&e.key.toLowerCase()==='v'&&selected.type==='element'){pasteTreeElement(selected.id);e.preventDefault()}else if(mod&&e.key.toLowerCase()==='d'&&selected.type==='element'){duplicateElement(selected.id);e.preventDefault()}else if(e.key==='Backspace'||e.key==='Delete'){if(selected?.id||selected?.nodeId||selected?.edgeId){deleteSelected();e.preventDefault()}}else if(mod&&e.key.toLowerCase()==='f'){e.preventDefault();$('searchBox').focus()}else if((e.altKey)&&e.key==='ArrowLeft'){navigationGoBack();e.preventDefault()}else if((e.altKey)&&e.key==='ArrowRight'){navigationGoForward();e.preventDefault()}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&selectedNodeIds.size){const step=e.shiftKey?10:1;const map={ArrowLeft:[-step,0],ArrowRight:[step,0],ArrowUp:[0,-step],ArrowDown:[0,step]};nudgeSelection(...map[e.key]);e.preventDefault()}});
document.addEventListener('keyup',e=>{if(e.code==='Space')spacePan=false});
const wrapEl=$('canvasWrap');
wrapEl.addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();const rect=wrapEl.getBoundingClientRect(),cx=e.clientX-rect.left,cy=e.clientY-rect.top,worldX=(wrapEl.scrollLeft+cx)/zoom,worldY=(wrapEl.scrollTop+cy)/zoom,next=Math.max(.25,Math.min(3,zoom*Math.exp(-e.deltaY*.0015)));zoom=next;renderCanvas();wrapEl.scrollLeft=worldX*zoom-cx;wrapEl.scrollTop=worldY*zoom-cy},{passive:false});
wrapEl.addEventListener('pointerdown',e=>{if(e.button===1||spacePan){panState={x:e.clientX,y:e.clientY,left:wrapEl.scrollLeft,top:wrapEl.scrollTop};wrapEl.classList.add('panning');wrapEl.setPointerCapture(e.pointerId);e.preventDefault()}});
wrapEl.addEventListener('pointermove',e=>{if(!panState)return;wrapEl.scrollLeft=panState.left-(e.clientX-panState.x);wrapEl.scrollTop=panState.top-(e.clientY-panState.y)});
wrapEl.addEventListener('pointerup',()=>{panState=null;wrapEl.classList.remove('panning')});

